'use client';

import { useState, type ReactNode } from 'react';
import { usePointerDrag } from './use-pointer-drag';
import { useReducedMotion } from './use-reduced-motion';
import './swipe-deck.css';

export interface SwipeDeckProps<T> {
  items: T[];
  renderCard: (item: T) => ReactNode;
  /** Index of the top card. */
  index: number;
  onIndexChange: (index: number) => void;
  /** Accessible name, for example "Destinations". */
  label: string;
  className?: string;
}

/**
 * A stack of cards. Drag the top card sideways to throw it off and reveal
 * the next; a short drag springs back. Vertical swipes still scroll the
 * page. Previous and Next do the same with buttons.
 */
export function SwipeDeck<T>({
  items,
  renderCard,
  index,
  onIndexChange,
  label,
  className = '',
}: SwipeDeckProps<T>) {
  const [dx, setDx] = useState<number | null>(null);
  const [leaving, setLeaving] = useState<{ index: number; dir: 1 | -1 } | null>(
    null
  );
  const reduced = useReducedMotion();
  const done = index >= items.length;

  const next = (dir: 1 | -1 = 1) => {
    if (done) return;
    if (!reduced) setLeaving({ index, dir });
    onIndexChange(index + 1);
  };

  const drag = usePointerDrag({
    onMove: ({ dx: x }) => setDx(x),
    onEnd: ({ dx: x, vx }, cancelled) => {
      setDx(null);
      if (cancelled) return;
      if (Math.abs(x) > 90 || Math.abs(vx) > 0.6) next(x < 0 ? -1 : 1);
    },
  });

  return (
    <div
      className={`mg-deck ${className}`}
      role='region'
      aria-roledescription='card stack'
      aria-label={label}
    >
      <div className='mg-deck__stack'>
        {done ? (
          <div className='mg-deck__end'>
            <strong>All {items.length} seen</strong>
            <span>Go back, or start again.</span>
          </div>
        ) : null}
        {items.map((item, i) => {
          const depth = i - index;
          if (depth < 0 && leaving?.index !== i) return null;
          if (depth > 2) return null;
          const top = depth === 0;
          const out = leaving?.index === i;
          return (
            <div
              key={i}
              className='mg-deck__card'
              data-top={top}
              data-leaving={out}
              aria-hidden={!top}
              style={
                out
                  ? {
                      transform: `translateX(${leaving!.dir * 130}%) rotate(${leaving!.dir * 18}deg)`,
                      opacity: 0,
                    }
                  : {
                      zIndex: 10 - depth,
                      transform:
                        top && dx !== null
                          ? `translateX(${dx}px) rotate(${dx / 18}deg)`
                          : `translateY(${depth * 10}px) scale(${1 - depth * 0.05})`,
                      transition: top && dx !== null ? 'none' : undefined,
                    }
              }
              onTransitionEnd={() => out && setLeaving(null)}
              {...(top ? drag : {})}
            >
              {renderCard(item)}
            </div>
          );
        })}
      </div>
      <div className='mg-deck__controls'>
        <button
          type='button'
          onClick={() => onIndexChange(Math.max(0, index - 1))}
          disabled={index === 0}
        >
          ← Previous
        </button>
        <span role='status'>
          {done ? 'End of stack' : `Card ${index + 1} of ${items.length}`}
        </span>
        {done ? (
          <button type='button' onClick={() => onIndexChange(0)}>
            Start again
          </button>
        ) : (
          <button type='button' onClick={() => next(1)}>
            Next →
          </button>
        )}
      </div>
    </div>
  );
}

.mg-deck {
  display: grid;
  gap: 12px;
  color: var(--mg-text, #ffffff);
}

.mg-deck__stack {
  position: relative;
  height: 170px;
}

.mg-deck__card,
.mg-deck__end {
  position: absolute;
  inset: 0;
  border-radius: 16px;
}

.mg-deck__card {
  padding: 18px;
  border: 1px solid var(--mg-line, #303030);
  background: #121212;
  box-shadow: 0 14px 28px -18px rgba(0, 0, 0, 0.5);
  transition:
    transform 380ms cubic-bezier(0.2, 0.9, 0.3, 1.1),
    opacity 380ms ease;
  touch-action: pan-y;
  user-select: none;
  -webkit-user-select: none;
}

.mg-deck__card[data-top='true'] {
  cursor: grab;
}

.mg-deck__card[data-leaving='true'] {
  z-index: 20;
  pointer-events: none;
}

.mg-deck__end {
  display: grid;
  place-content: center;
  gap: 4px;
  border: 1px dashed #474747;
  color: #b8b8b8;
  text-align: center;
}

.mg-deck__end strong {
  color: var(--mg-text, #ffffff);
}

.mg-deck__controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.mg-deck__controls span {
  color: #b8b8b8;
  font-size: 13px;
}

.mg-deck__controls button {
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 8px;
  background: #121212;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-deck__controls button:disabled {
  opacity: 0.45;
  cursor: default;
}

.mg-deck__controls button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-deck__card {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 150) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
